(async () => {
      const g = __rhf.game;
      g.state.settings.autoQuality = false;
      g.setQuality('low');
      g.bears.directorT = 1e9;
      g.env.timeScale = 0;
      g.env.setTime(9);
      g.hud.firstShown = -1000;
      g.hud.hint('', 0);
      // the boxes of the controls, and which of them overlap
      window.__measure = () => {
        const sel = {
          wardrobe: '#btn-wardrobe', map: '#btn-map', journal: '#btn-journal', pause: '#btn-pause', bite: '#bite-pill', clock: '#hud-time',
          compass: '#compass', goal: '#objective', money: '#hud-money', health: '.top-left .stat.health', cooler: '#chip-cooler', lure: '#chip-lure',
          minimap: '#minimap', run: '#btn-run', primary: '#btn-primary', tool: '#btn-tool',
        };
        const boxes = Object.entries(sel).map(([id, q]) => {
          const el = document.querySelector(q);
          if (!el || el.hidden || el.closest('[hidden]')) return id + ' hidden';
          const b = el.getBoundingClientRect();
          return { id, x: Math.round(b.left), y: Math.round(b.top), w: Math.round(b.width), h: Math.round(b.height) };
        });
        const vis = boxes.filter((b) => typeof b === 'object' && b.w > 0);
        const hits = [];
        for (let i = 0; i < vis.length; i++)
          for (let j = i + 1; j < vis.length; j++) {
            const a = vis[i];
            const b = vis[j];
            if (a.x < b.x + b.w && b.x < a.x + a.w && a.y < b.y + b.h && b.y < a.y + a.h) hits.push(a.id + ' x ' + b.id);
          }
        return boxes.map((b) => (typeof b === 'string' ? b : `${b.id} ${b.x},${b.y} ${b.w}x${b.h}`)).join(' | ') + ' || overlaps: ' + (hits.join(', ') || 'none');
      };
      // wait until the goal and the buttons are on screen
      const t0 = performance.now();
      while (performance.now() - t0 < 120000) {
        const o = document.getElementById('objective');
        if (o.getBoundingClientRect().width > 0 && !document.getElementById('btn-run').hidden) break;
        await new Promise((r) => setTimeout(r, 300));
      }
      return __measure();
    })()

